head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setColumnNodeSet("col_select", "data:dataList3", "col1", "col2");
};
scwin.trigger2_onclick = function(e) {
    gridView1.setColumnNodeSet("col_select", "data:dataList2", "col1", "col2");
};
scwin.trigger3_onclick = function(e) {
    gridView1.setColumnNodeSet("col_select", "data:dataList4", "col1", "col2");
};
scwin.trigger4_onclick = function(e) {
    gridView1.setColumnNodeSet("col_select", "data:dataList4", "col3", "col2");
};
scwin.checklog = function() {
    try {
        log1 = gridView1.getInputType("col1");
        log2 = gridView1.getInputType("col_select");
        log3 = gridView1.getInputType("col3");
        log4 = gridView1.getInputType("col4");
        log5 = gridView1.getDataType("col1");
        log6 = gridView1.getDataType("col_select");
        log7 = gridView1.getDataType("col2");
        log8 = gridView1.getDataType("col3");
        console.log(log1);
        console.log(log2);
        console.log(log3);
        console.log(log4);
        console.log(log5);
        console.log(log6);
        console.log(log7);
        console.log(log8);
        if (log1 == "text" && log2 == "select" && log3 == "text" && log4 == "text" && log5 == "number" && log6 == "text" && typeof log7 == "undefined" && log8 == "number") {
            logShowed = true;
        } else {
            logShowed = false;
        }
    } catch (err) {
        logShowed = false;
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 F12를 클릭하여 콘솔창을 실행한다.
    //gridView1.getInputType("col1");
    //gridView1.getInputType("col_select");
    //gridView1.getInputType("col3");
    //gridView1.getInputType("col4");
    //gridView1.getDataType("col1");
    //gridView1.getDataType("col_select");
    //gridView1.getDataType("col2");
    //gridView1.getDataType("col3");
    //1. Run the sample file and click F12 to launch the console window.
    //Verify step 1. 개발자모드인 콘솔창이 보여진다.
    //1. A console window is displayed in developer mode.
    //Test step 2. 아래와 같이 입력하여 결과값이 나오는지 확인한다.
    //2. Enter the following and check whether the result is displayed.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.checklog()");
    //Verify step 2. 8개의 콜솔창 입력에 대한 값이 정상적으로 보여진다.(이전에는 기능이 없었음)
    //2. The values ​​for the eight call window inputs are displayed normally (previously no function).
    WebSquare.wUnit.addCommand("assert", "logShowed", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    var ddd;
    window.data = [];
    window.data2 = [];
    window.data3 = [];
    window.data4 = [];
    for (var i = 0; i < 20; i++) {
        for (var j = 0; j < 4; j++) {
            window.oneData = 4 * i + j;
            data.push(oneData);
            data2.push(oneData);
            data2.push(oneData);
            window.oneData2 = 4 * (19 - i) + j;
            data3.push(oneData);
            data3.push(oneData2);
            data4.push(i + "_" + j);
            data4.push(oneData);
            data4.push(i + "--" + j);
        }
    }
    dataList4.setData(data4);
    dataList3.setData(data3);
    dataList2.setData(data2);
    dataList1.setData(data);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    window.logShowed = undefined;
    window.log1 = "";
    window.log2 = "";
    window.log3 = "";
    window.log4 = "";
    window.log5 = "";
    window.log6 = "";
    window.log7 = "";
    window.log8 = "";
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
